function rrSharedPath(o,kind=1){return rrSharedChains(kind).map(({pts,ns})=>'M'+pts.map((p,i)=>(p[0]+ns[i][0]*o).toFixed(2)+' '+(p[1]+ns[i][1]*o).toFixed(2)).join('L')).join('')}
