function rrCityCheckIn(name){
 if(!rrCheckInMemo){rrCheckInMemo=new Map();const air=rrMajorAirports();
  for(const n of MAJOR_STATIONS){if(rrIsAirport(n))continue;const hit=new Set();
   for(const t of TRAINS){const i=t.route.findIndex(r=>r[0]===n);if(i<0)continue;
    for(let k=i+1;k<t.route.length;k++){const a=t.route[k][0];if(air.has(a)&&timeOrdinal(t.route[k][1])-timeOrdinal(t.route[i][1])<=90&&rrMetro(S.get(n)?.city).includes(rrAirportCity(a)))hit.add(a)}}
   if(hit.size)rrCheckInMemo.set(n,[...hit].sort())}}
 return rrCheckInMemo.get(name)||null}
/* City check-in on trains and journeys (user 2026-11-22 "shorter, use City check-in available"): shown at a station with City
   check-in when this train reaches (by stop `last`, within 90 min) one of the airports checked in there; details stay in the facility tab. */
const RR_CHECKIN_LIMIT=['From 24 hours to 90 minutes before your flight','De 24 h à 90 min avant votre vol'];
function rrCheckInHere(t,i,last=t.route.length-1){const air=rrCityCheckIn(t.route[i]?.[0]);if(!air)return false;
 for(let k=i+1;k<=last;k++)if(air.includes(t.route[k][0])&&timeOrdinal(t.route[k][1])-timeOrdinal(t.route[i][1])<=90)return true;return false}   /* same 90-min rule as the station's check-in */
