function rrCheckInOpenAt(name,ord,date){const h=STATION_HOURS[rrStationTier(name)]?.['RR Services'];if(!h)return false;
 const day=(date.getDay()+Math.floor(ord/1440))%7,m=((ord%1440)+1440)%1440,t=rrHoursOn(h,day);return !!t&&m>=t[0]&&m<t[1]}
function rrCheckInShown(t,i,last,date){return rrCheckInHere(t,i,last)&&rrCheckInOpenAt(t.route[i][0],stopOrdinal(t,i),date)}
/* train details: the day the current stop's time falls on, and every other stop counted from it */
