function rrJourneyBoardDay(j,leg){const d=rrJourneyDate();d.setDate(d.getDate()+(j.whenTomorrow?1:0)+Math.floor(((j.legs[0].dep%1440)+(leg.dep-j.legs[0].dep))/1440));return d}
